# attach fwshift-addresses: 0.0.0.0-10.19.255.255 10.21.0.0-10.29.255.255 10.30.99.0/24 10.31.0.0-10.39.255.255 10.40.1.0-198.51.99.255 198.51.101.0-255.255.255.255
G1=$(group 'fwshift-addresses' 'FWShift: for the interfaces of 0.0.0.0-10.19.255.255 10.21.0.0-10.29.255.255 10.30.99.0/24 10.31.0.0-10.39.255.255 10.40.1.0-198.51.99.255 198.51.101.0-255.255.255.255') || exit 1
