G2=$(group 'fwshift-addresses-2' 'FWShift: for the interfaces of 10.20.0.0/24 10.20.2.0/24 10.20.4.0/24 10.20.6.0-10.20.6.9 10.20.6.11-10.20.6.255 10.20.9.0-10.20.255.255') || exit 1
# attach fwshift-WEB_SERVERS: 10.20.1.0/24
G3=$(group 'fwshift-WEB_SERVERS' 'FWShift: for the interfaces of 10.20.1.0/24') || exit 1
# attach fwshift-addresses-3: 10.20.3.0/24
G4=$(group 'fwshift-addresses-3' 'FWShift: for the interfaces of 10.20.3.0/24') || exit 1
# attach fwshift-addresses-4: 10.20.5.0/24
G5=$(group 'fwshift-addresses-4' 'FWShift: for the interfaces of 10.20.5.0/24') || exit 1
# attach fwshift-addresses-5: 10.20.6.10
G6=$(group 'fwshift-addresses-5' 'FWShift: for the interfaces of 10.20.6.10') || exit 1
# attach fwshift-addresses-6: 10.20.7.0/24
G7=$(group 'fwshift-addresses-6' 'FWShift: for the interfaces of 10.20.7.0/24') || exit 1
# attach fwshift-addresses-7: 10.20.8.0/24
G8=$(group 'fwshift-addresses-7' 'FWShift: for the interfaces of 10.20.8.0/24') || exit 1
# attach fwshift-addresses-8: 10.30.0.0-10.30.98.255 10.30.100.0-10.30.255.255
G9=$(group 'fwshift-addresses-8' 'FWShift: for the interfaces of 10.30.0.0-10.30.98.255 10.30.100.0-10.30.255.255') || exit 1
# attach fwshift-addresses-9: 10.40.0.0/24
G10=$(group 'fwshift-addresses-9' 'FWShift: for the interfaces of 10.40.0.0/24') || exit 1
# attach fwshift-addresses-10: 198.51.100.0/24
G11=$(group 'fwshift-addresses-10' 'FWShift: for the interfaces of 198.51.100.0/24') || exit 1
# attach fwshift-addresses-ipv6: ::-2001:db8:1f:ffff:ffff:ffff:ffff:ffff 2001:db8:20:100::-2001:db8:bac:ffff:ffff:ffff:ffff:ffff 2001:db8:bae::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
G12=$(group 'fwshift-addresses-ipv6' 'FWShift: for the interfaces of ::-2001:db8:1f:ffff:ffff:ffff:ffff:ffff 2001:db8:20:100::-2001:db8:bac:ffff:ffff:ffff:ffff:ffff 2001:db8:bae::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff') || exit 1
# attach fwshift-addresses-ipv6-2: 2001:db8:20::/64 2001:db8:20:2::-2001:db8:20:ff:ffff:ffff:ffff:ffff
G13=$(group 'fwshift-addresses-ipv6-2' 'FWShift: for the interfaces of 2001:db8:20::/64 2001:db8:20:2::-2001:db8:20:ff:ffff:ffff:ffff:ffff') || exit 1
# attach fwshift-WEB_SERVERS-ipv6: 2001:db8:20:1::/64
G14=$(group 'fwshift-WEB_SERVERS-ipv6' 'FWShift: for the interfaces of 2001:db8:20:1::/64') || exit 1
# attach fwshift-addresses-ipv6-3: 2001:db8:bad::/48
G15=$(group 'fwshift-addresses-ipv6-3' 'FWShift: for the interfaces of 2001:db8:bad::/48') || exit 1

